Rscript - <<'RS'
for (f in c('inputs/res_1vs97.rds','inputs/res_1vs98.rds')) {
 x<-readRDS(f); rn<-attr(x,'rownames'); ld<-attr(x,'listData'); cat('\\n',f,'\\n')
 for(g in c('PA14_19120','PA14_45940','PA14_35160')) {i<-match(g,rn); cat(g,'index',i,'LFC',ld[['log2FoldChange']][i],'baseMean',ld[['baseMean']][i],'p',ld[['pvalue']][i],'\\n')}
}
RS"

